{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C03"],
      "claim": "Aniracetam is very rapidly absorbed but undergoes extensive first-pass metabolism, resulting in extremely low oral bioavailability in humans; this high-transfer analogue supports a low-F prediction for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Free baicalein has low oral bioavailability in humans, consistent with phenolic/heteroaromatic scaffolds undergoing conjugation and efflux; supports low F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Defibrotide absolute oral bioavailability was 2.6–13% versus IV in patients, a direct sub-20% measurement; high transferability supports low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Chrysin oral bioavailability in humans is 0.003–0.02% after a 400 mg dose, showing that polyphenolic, poorly soluble compounds can have extremely low systemic exposure; supports low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Acamprosate has about 11% oral bioavailability under fasting conditions, demonstrating that small ionizable polar molecules can be poorly absorbed; supports low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Rebamipide has under 10% oral bioavailability in humans and shares carboxylic acid/aromatic heterocycle features with the query; supports low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Tilidine systemic bioavailability is 7.6% in humans due to first-pass metabolism, supporting low F for a lipophilic drug with metabolic liability; relevant to the query's likely first-pass clearance.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Aspirin in solution can have 65–75% absolute bioavailability, showing that a small carboxylic acid can be well absorbed; however, this is formulation-dependent and less applicable to the larger, poorly soluble query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The preponderance of high-transfer experimental evidence shows low oral bioavailability for diverse compounds sharing the query's ionizable/phenolic and poorly soluble character; direct absolute F values are consistently below 20%. The only high-F evidence (aspirin solution) is formulation-dependent and outweighed by the more transferable low-F analogues. Therefore predict low.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule.",
    "Most analogues are structurally distant; transfer relies on shared physicochemical liabilities rather than exact scaffold.",
    "Query-specific solubility, permeability, and first-pass metabolism data are absent.",
    "Aspirin high-F data are formulation-dependent and not directly applicable."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

